#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{
 require(argc==2,"usage affine_extraction_independent_audit OUTPUT_DIR");fs::path out=argv[1];auto start=std::chrono::steady_clock::now();rref_option_t opt;opt->pool.reset(1);
 auto k=read_matrix(out/"SEW_6p2_affine_TR_matrix.wxf"),o=read_matrix(out/"affine_tail_w8_invariant_TF175_origin.wxf"),j=read_matrix(out/"suffix_TR92_to_TF175.wxf");
 size_t nf=o.nrow,nx=nf*92;require(k.nrow==4&&k.ncol==nx+1&&nf==35598&&o.ncol==175&&j.nrow==92&&j.ncol==175,"input dimensions");
 size_t point=4,alphaRows=0;for(size_t a=0;a<4;++a)if(k[a].find(index(nx))){point=a;++alphaRows;}require(alphaRows==1,"one alpha-supported kernel row");Q alpha=*k[point].find(index(nx));
 Mat x(nf,92),directions(3,nx);size_t d=0;for(size_t a=0;a<4;++a)if(a==point){for(auto[c,v]:k[a])if(size_t(c)<nx)x[c/92].push_back(index(c%92),v/alpha);}else directions[d++]=k[a];
 auto expected=mul(x,j);for(size_t a=0;a<nf;++a){for(auto[b,v]:o[a])expected[a].push_back(b,v);normalize(expected[a]);}
 auto t=read(out/"sewn_affine_w8_origin.wxf");require(t.rank()==3&&t.dim(0)==1&&t.dim(1)==nf&&t.dim(2)==175,"output origin axes");auto flat=flatten(t);t.clear();Mat actual(nf,175);for(auto[c,v]:flat[0])actual[c/175].push_back(index(c%175),v);flat.clear();require(equal(expected,actual),"every origin coefficient O + Xpoint J/alpha");
 t=read(out/"sewn_affine_w8_directions_TR92.wxf");require(t.rank()==3&&t.dim(0)==3&&t.dim(1)==nf&&t.dim(2)==92,"output direction axes");auto nd=flatten(t);t.clear();Chart cd(directions,opt),cn(nd,opt);auto maps=cd.coordinates(nd),back=cn.coordinates(directions);require(equal(mul(maps,directions),nd)&&equal(mul(back,nd),directions),"complete homogeneous direction row-space equality");
 auto e=read_matrix(out/"lastpair_E.wxf");require(e.nrow==175&&mul(j,e).nnz()==0,"J annihilates complete local affine tail map");auto delta=expected;for(size_t a=0;a<nf;++a){for(auto[b,v]:o[a])delta[a].push_back(b,-v);normalize(delta[a]);}require(mul(delta,e).nnz()==0,"full extracted origin has exactly the original affine tail RHS");
 std::ofstream receipt(out/"affine_extraction_independent_audit.json");receipt<<"{\"all_checks_pass\":true,\"augmented_kernel_dimension\":4,\"alpha_supported_rows\":1,\"affine_dimension\":3,\"prefix_dimension\":35598,\"origin_nonzeros\":"<<actual.nnz()<<",\"directions_nonzeros\":"<<nd.nnz()<<",\"full_origin_coefficients_checked\":true,\"directions_exact_rowspace_equality\":true,\"local_affine_tail_RHS_preserved\":true,\"scope\":\"Independent exact coordinate extraction and tail reconstruction audit. The saved full-operator modular rank and height certificate establish sewing completeness; this audit does not rerun that large operator. Boundary regularity and reserved targets are separate.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"PASS all origin and direction coefficients and tail RHS; seconds="<<seconds(start)<<std::endl;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
